<?php
require_once __DIR__.'/_init.php';require_once __DIR__.'/../includes/admin-ui.php';$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'save';
 try{
  if($action==='delete'){$id=(int)($_POST['id']??0);$q=$pdo->prepare('SELECT gambar FROM programs WHERE id=?');$q->execute([$id]);$old=$q->fetchColumn();$pdo->prepare('DELETE FROM programs WHERE id=?')->execute([$id]);remove_uploaded_image(is_string($old)?$old:null);flash('success','Program berhasil dihapus.');}
  else{$id=(int)($_POST['id']??0);$title=trim((string)($_POST['judul']??''));$desc=trim((string)($_POST['deskripsi']??''));$status=($_POST['status']??'draft')==='publikasi'?'publikasi':'draft';$order=(int)($_POST['urutan']??0);if($title===''||$desc==='')throw new RuntimeException('Judul dan deskripsi wajib diisi.');$img=null;if(isset($_FILES['gambar']))$img=upload_image($_FILES['gambar'],'program');
   if($id>0){if($img){$q=$pdo->prepare('SELECT gambar FROM programs WHERE id=?');$q->execute([$id]);$old=$q->fetchColumn();$pdo->prepare('UPDATE programs SET judul=?,deskripsi=?,gambar=?,status=?,urutan=? WHERE id=?')->execute([$title,$desc,$img,$status,$order,$id]);remove_uploaded_image(is_string($old)?$old:null);}else{$pdo->prepare('UPDATE programs SET judul=?,deskripsi=?,status=?,urutan=? WHERE id=?')->execute([$title,$desc,$status,$order,$id]);}flash('success','Program berhasil diperbarui.');}
   else{$pdo->prepare('INSERT INTO programs(judul,deskripsi,gambar,status,urutan) VALUES(?,?,?,?,?)')->execute([$title,$desc,$img,$status,$order]);flash('success','Program baru berhasil ditambahkan.');}}
 }catch(Throwable $e){flash('error',$e instanceof RuntimeException?$e->getMessage():'Gagal menyimpan program. Periksa database dan folder uploads.');}
 header('Location: program.php');exit;
}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM programs WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}$rows=$pdo->query('SELECT * FROM programs ORDER BY urutan,id')->fetchAll();admin_header('Kelola Program','program'); ?>
<section class="panel"><div class="panel-head"><div><h2><?= $edit?'Edit program':'Tambah program' ?></h2><p class="panel-subtitle">Konten yang berstatus publikasi akan otomatis muncul di halaman Program.</p></div></div><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div class="form-grid"><div class="field"><label>Nama program</label><input name="judul" required maxlength="180" value="<?= e($edit['judul']??'') ?>"></div><div class="field"><label>Urutan tampil</label><input type="number" name="urutan" min="0" value="<?= (int)($edit['urutan']??0) ?>"></div><div class="field"><label>Status</label><select name="status"><option value="draft" <?= ($edit['status']??'draft')==='draft'?'selected':'' ?>>Draft</option><option value="publikasi" <?= ($edit['status']??'')==='publikasi'?'selected':'' ?>>Publikasikan</option></select></div><div class="field"><label>Foto program</label><input type="file" name="gambar" accept="image/jpeg,image/png,image/webp"><small class="hint">JPG, PNG, WEBP maksimal 5 MB.</small><?php if(!empty($edit['gambar'])): ?><img class="image-thumb" style="margin-top:8px" src="../<?= e($edit['gambar']) ?>" alt="Foto program saat ini"><?php endif; ?></div></div><div class="field"><label>Deskripsi</label><textarea name="deskripsi" required><?= e($edit['deskripsi']??'') ?></textarea></div><button class="btn btn-gold" type="submit"><?= $edit?'Simpan perubahan':'Tambah program' ?></button><?php if($edit): ?> <a class="btn btn-light" href="program.php">Batal</a><?php endif; ?></form></section>
<section class="panel"><div class="panel-head"><div><h2>Daftar program</h2><p class="panel-subtitle"><?= count($rows) ?> data tersimpan.</p></div></div><?php if(!$rows): ?><div class="empty">Belum ada program.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Foto</th><th>Program</th><th>Urutan</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?php if($r['gambar']): ?><img class="image-thumb" src="../<?= e($r['gambar']) ?>" alt=""><?php else: ?>—<?php endif; ?></td><td><b><?= e($r['judul']) ?></b><br><small><?= e(mb_strimwidth($r['deskripsi'],0,100,'…')) ?></small></td><td><?= (int)$r['urutan'] ?></td><td><span class="pill <?= $r['status']==='publikasi'?'green':'orange' ?>"><?= e(ucfirst($r['status'])) ?></span></td><td><div class="table-actions"><a class="btn btn-light btn-sm" href="?edit=<?= (int)$r['id'] ?>">Edit</a><form class="inline-form" method="post" onsubmit="return confirm('Hapus program ini?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn btn-danger btn-sm">Hapus</button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php admin_footer(); ?>
